func TestPrivateSocketDirectory(t *testing.T) {
	dir, e := privateSocketDirectory()
	if e != nil {
		t.Fatal(e)
	}
	defer os.Remove(dir)
	info, e := os.Stat(dir)
	if e != nil || info.Mode().Perm() != 0700 || int(info.Sys().(*syscall.Stat_t).Uid) != os.Getuid() || len([]byte(filepath.Join(dir, "api.sock"))) >= 100 {
		t.Fatal(info, e)
	}
}

