	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	if _, err := conn.Subscribe("ts.orch.v1.gru.obs.slow", func(message *nats.Msg) {
		time.Sleep(2 * time.Second)
		_ = message.Respond(nil)
	}); err != nil {
		t.Fatal(err)
	}
