shell_fixture.text:
func templateRunShell(t *testing.T, base, bin, path string) script.Result {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "/bin/sh", path)
	cmd.Dir = base
	cmd.Env = append(os.Environ(), "PATH="+bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error { return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL) }
	cmd.WaitDelay = time.Second
	output, err := cmd.CombinedOutput()
	if ctx.Err() != nil {
		t.Fatalf("guest shell exceeded five seconds: %v; %s", ctx.Err(), output)
	}
	code := 0
	if err != nil {
		if exit, ok := errors.AsType[*exec.ExitError](err); ok {
			code = exit.ExitCode()
		} else {
			t.Fatal(err)
		}
	}
	return script.Result{Stdout: string(output), Code: code}
}

new_qualification.text:
func New(ctx context.Context, m Object, raw []byte, inputs map[string]string, runDir, repoRoot string) (*Qualification, error) {
	q := &Qualification{Manifest: m, RawManifest: raw, Inputs: inputs, Root: runDir, Managed: m["profile"] == ManagedVolumeProfile, ctx: ctx, TestResults: Object{}, CleanupErrors: []string{}, SourcePaths: map[string]string{}, SourceHashes: map[string]string{}, StartedAt: time.Now().UTC().Format(time.RFC3339Nano), SourceStable: true, IsMounted: IsMountPoint}
	q.Logs = filepath.Join(runDir, "logs")
	q.Commands = filepath.Join(runDir, "commands")
	q.Images = filepath.Join(runDir, "images")
	q.MountRoot = filepath.Join(runDir, "mount")
	q.Stage = filepath.Join(runDir, "stage")
	q.Image = filepath.Join(q.Images, "member-status.ext4")
	q.ManagedVolumeImage = filepath.Join(q.Images, "managed-volume.ext4")
	q.MountPath = filepath.Join(q.MountRoot, "guest")
	q.Events = &EventLog{Path: filepath.Join(q.Logs, "events.json")}
	q.CommandRunner = &CommandRunner{Root: runDir, Events: q.Events}
	q.Command = q.CommandRunner.Run
	if repoRoot != "" {
		paths := map[string]string{"tests": "tests/firecracker/memberstatus/main_test.go", "memberstatus_probe_source": "tests/firecracker/memberstatus/main.go", "native_test_support": "internal/testutil/script/script.go", "readme": "tests/firecracker/README.md", "focused_go_test_source": "internal/host/runner_test.go", "shared_runtime": "internal/qualification/firecracker/runtime.go", "go_mod": "go.mod", "go_sum": "go.sum"}
		if q.Managed {
			paths["focused_go_test_source"] = "internal/host/managed_runtime_firecracker_test.go"
		}
		files, e := os.ReadDir(filepath.Join(repoRoot, "internal/qualification/memberstatus"))
		if e != nil {
			return nil, e
		}
		for _, f := range files {
			if strings.HasSuffix(f.Name(), ".go") || strings.HasSuffix(f.Name(), ".sh") {
				paths["driver/"+f.Name()] = filepath.Join("internal/qualification/memberstatus", f.Name())
			}
		}
		for name, path := range paths {
			path = filepath.Join(repoRoot, path)
			digest, e := firecracker.Digest(path)
			if e != nil {
				return nil, e
			}
			q.SourcePaths[name] = path
			q.SourceHashes[name] = digest
		}
		// Linux exposes the executing inode here even if the executable's
		// original pathname is replaced while qualification is running.
		digest, err := firecracker.Digest("/proc/self/exe")
		if err != nil {
			return nil, err
		}
		q.SourcePaths["driver_binary"] = "/proc/self/exe"
		q.SourceHashes["driver_binary"] = digest
	}
	return q, nil
}

qualification_failure.text:
func (q *Qualification) fail(e error) {
	if q.err == nil && e != nil {
		q.err = e
	}
}
func (q *Qualification) Err() error { return q.err }
func (q *Qualification) note(event string, fields Object) {
	q.Events.Add(event, fields)
	q.fail(q.Events.Err)
}

prepare_dirs.text:
func (q *Qualification) PrepareDirs() error {
	if e := os.Mkdir(q.Root, 0700); e != nil {
		return e
	}
	for _, path := range []string{q.Logs, q.Commands, q.Images, q.MountRoot, q.Stage} {
		if e := os.Mkdir(path, 0700); e != nil {
			return e
		}
	}
	if e := os.WriteFile(filepath.Join(q.Root, "manifest.json"), q.RawManifest, 0600); e != nil {
		return e
	}
	q.note("qualification_start", Object{"manifest_sha256": shaBytes(q.RawManifest), "source_commits": q.Manifest["source_commits"], "run_dir": q.Root, "profile": q.Manifest["profile"], "go_test_name": q.Manifest["go_test_name"]})
	return q.err
}

unmount.text:
func (q *Qualification) Unmount() error {
	saved := q.err
	q.err = nil
	ctx := q.ctx
	q.ctx = context.WithoutCancel(ctx)
	defer func() {
		q.ctx = ctx
		if saved != nil {
			q.err = saved
		}
	}()
	if !q.IsMounted(q.MountPath) {
		q.MountOwned = false
		q.removeMountpoint()
		return q.err
	}
	if !q.MountOwned {
		return fmt.Errorf("refusing to unmount unowned mount: %s", q.MountPath)
	}
	q.sudo("umount", time.Minute, "umount", q.MountPath)
	if !q.IsMounted(q.MountPath) {
		q.MountOwned = false
		q.removeMountpoint()
	}
	if q.MountOwned {
		q.fail(fmt.Errorf("owned mount remains active after umount"))
	}
	q.note("image_unmounted", Object{"mount": q.MountPath})
	return q.err
}

rootfs_validation.text:
func (q *Qualification) ValidateGuestRootfs() {
	required := []string{"/usr/lib/systemd/systemd", "/usr/bin/setpriv", "/usr/bin/curl", "/usr/bin/systemctl"}
	if q.Managed {
		required = []string{"/usr/lib/systemd/systemd", "/usr/bin/systemctl", ManagedVolumeBlkidPath, "/usr/bin/findmnt", "/usr/bin/mountpoint", "/usr/bin/readlink"}
	}
	for _, path := range required {
		host, e := GuestPath(q.MountPath, path)
		q.fail(e)
		if q.err != nil {
			return
		}
		info, e := os.Stat(host)
		if e != nil || !info.Mode().IsRegular() {
			q.fail(fmt.Errorf("guest rootfs is missing required probe executable: %s", path))
			return
		}
	}
	text, oversized, e := ReadGuestRegularFile(q.MountPath, "/var/lib/dpkg/status", 16<<20)
	q.fail(e)
	if oversized {
		q.fail(fmt.Errorf("guest package status database exceeded its read bound"))
		return
	}
	version := 0
	for stanza := range strings.SplitSeq(text, "\n\n") {
		fields := map[string]string{}
		for line := range strings.SplitSeq(stanza, "\n") {
			k, v, ok := strings.Cut(line, ": ")
			if ok {
				fields[k] = v
			}
		}
		if fields["Package"] == "systemd" && fields["Status"] == "install ok installed" {
			m := regexp.MustCompile(`^(?:[0-9]+:)?([0-9]+)(?:\.|-|$)`).FindStringSubmatch(fields["Version"])
			if m != nil {
				version, _ = strconv.Atoi(m[1])
			}
			break
		}
	}
	if version < 255 {
		q.fail(fmt.Errorf("guest requires an installed systemd package at version 255 or newer"))
		return
	}
	q.note("guest_systemd_version", Object{"version": version, "source": "dpkg-status"})
}

source_stability.text:
func (q *Qualification) checkSourceStability() {
	q.SourceHashesAfter = map[string]string{}
	for name, path := range q.SourcePaths {
		digest, e := firecracker.Digest(path)
		if e != nil {
			q.SourceStable = false
			q.Failure += fmt.Sprintf("; local source disappeared during qualification: %s: %v", path, e)
			return
		}
		q.SourceHashesAfter[name] = digest
	}
	q.SourceStable = maps.Equal(q.SourceHashes, q.SourceHashesAfter)
	if !q.SourceStable {
		q.Failure += "; local source files changed during qualification"
		q.note("source_changed_during_qualification", Object{"initial": q.SourceHashes, "observed": q.SourceHashesAfter})
	}
}

cleanup_socket.text:
func (q *Qualification) CleanupSocketDirectory() {
	if q.SocketDir == "" {
		return
	}
	if q.VM != nil && q.VM.Process != nil && (!q.VM.Process.Reaped || !q.VM.ProcessGroupStopped) {
		q.CleanupErrors = append(q.CleanupErrors, "API socket directory retained while Firecracker is live: "+q.SocketDir)
		return
	}
	if q.VM != nil {
		socket := q.VM.SocketPath()
		info, e := os.Lstat(socket)
		if e == nil {
			if info.Mode()&os.ModeSocket == 0 {
				q.CleanupErrors = append(q.CleanupErrors, "unexpected non-socket at owned API path: "+socket)
				return
			}
			if e = os.Remove(socket); e != nil {
				q.CleanupErrors = append(q.CleanupErrors, e.Error())
				return
			}
		} else if !os.IsNotExist(e) {
			q.CleanupErrors = append(q.CleanupErrors, e.Error())
			return
		}
	}
	if e := os.Remove(q.SocketDir); e != nil && !os.IsNotExist(e) {
		q.CleanupErrors = append(q.CleanupErrors, "remove owned API socket directory: "+e.Error())
		return
	}
	q.note("api_socket_dir_removed", Object{"path": q.SocketDir})
}

cleanup_image.text:
func (q *Qualification) CleanupImage() {
	stopped := q.VM == nil || q.VM.Process == nil || (q.VM.Process.Reaped && q.VM.ProcessGroupStopped)
	commandsStopped := !q.CommandRunner.Pending()
	mounted := q.IsMounted(q.MountPath)
	safe := stopped && commandsStopped && !mounted && !q.MountOwned
	images := []string{q.Image}
	if q.Managed {
		images = append(images, q.ManagedVolumeImage)
	}
	for _, image := range images {
		if !lexists(image) {
			continue
		}
		if !safe || q.Failure != "" || len(q.CleanupErrors) > 0 || q.Events.Err != nil {
			q.note("private_image_retained", Object{"image": image, "stopped": stopped, "commands_stopped": commandsStopped, "mounted": mounted, "tracked_mount": q.MountOwned, "reason": "qualification or cleanup failed; preserve guest-side evidence"})
			continue
		}
		if e := os.Remove(image); e != nil {
			q.CleanupErrors = append(q.CleanupErrors, "remove stopped and unmounted private image: "+e.Error())
		} else {
			q.note("private_image_removed", Object{"image": image})
		}
	}
}

summary.text:
func (q *Qualification) Summary() Object {
	outcome := "PASS"
	if len(q.CleanupErrors) > 0 {
		outcome = "CLEANUP_FAILED"
	} else if q.Failure != "" {
		outcome = "FAILED"
	}
	hashes, paths := Object{}, Object{}
	for _, name := range q.names() {
		hashes[name] = q.expected(name)
		paths[name] = q.Inputs[name]
	}
	logs := Object{"events": q.Events.Path, "serial": filepath.Join(q.Logs, "guest-serial.log"), "vmm": filepath.Join(q.Logs, "firecracker-vmm.log")}
	if q.Managed {
		logs["managed_volume_test"] = filepath.Join(q.Logs, "guest-managed-volume-test.log")
	} else {
		logs["go_host_test"] = filepath.Join(q.Logs, "guest-go-host-test.log")
		logs["rust_test"] = filepath.Join(q.Logs, "guest-rust-test.log")
	}
	var socket any
	if q.SocketDir != "" {
		socket = q.SocketDir
	}
	summary := Object{"schema_version": 1, "outcome": outcome, "failure": q.Failure, "cleanup_errors": q.CleanupErrors, "cleanup_clean": len(q.CleanupErrors) == 0, "started_at": q.StartedAt, "finished_at": time.Now().UTC().Format(time.RFC3339Nano), "run_dir": q.Root, "source_commits": q.Manifest["source_commits"], "manifest_sha256": shaBytes(q.RawManifest), "local_source_hashes": q.SourceHashes, "local_source_hashes_after": q.SourceHashesAfter, "local_source_stable": q.SourceStable, "input_hashes": hashes, "input_paths": paths, "resources": Object{"guest_ram_mib": GuestRAMMiB, "guest_vcpus": GuestVCPUs, "guest_network_interfaces": []any{}, "service_name": ServiceName, "service_memory_max": "5G", "service_delegate": true, "service_delegate_subgroup": "supervisor", "private_image": q.Image, "private_image_removed": !lexists(q.Image), "private_image_retained": lexists(q.Image), "api_socket_dir": socket, "api_socket_dir_removed": q.SocketDir == "" || !lexists(q.SocketDir)}, "tests": q.TestResults, "logs": logs, "events": q.Events.Entries}
	if q.Managed {
		summary["profile"] = ManagedVolumeProfile
		summary["go_test_name"] = q.Manifest["go_test_name"]
		summary["managed_volume"] = Object{"filesystem_uuid": ManagedVolumeUUID, "private_image": q.ManagedVolumeImage, "private_image_removed": !lexists(q.ManagedVolumeImage), "private_image_retained": lexists(q.ManagedVolumeImage), "device": "/dev/oracleoci/oraclevdb", "mount_path": MountPath}
	} else {
		summary["rust_test_name"] = q.Manifest["rust_test_name"]
	}
	return summary
}

private_socket.text:
func privateSocketDirectory() (string, error) {
	dir, e := os.MkdirTemp("/tmp", "tsms-")
	if e != nil {
		return "", e
	}
	if e = os.Chmod(dir, 0700); e != nil {
		os.Remove(dir)
		return "", e
	}
	if len([]byte(filepath.Join(dir, "api.sock"))) >= 100 {
		os.Remove(dir)
		return "", fmt.Errorf("Unix socket path too long")
	}
	return dir, nil
}

manifest_load.text:
func LoadManifest(path string) (Object, []byte, map[string]string, error) {
	raw, e := os.ReadFile(path)
	if e != nil {
		return nil, nil, nil, e
	}
	var m Object
	if e = json.Unmarshal(raw, &m); e != nil {
		return nil, nil, nil, e
	}
	if m == nil {
		return nil, nil, nil, fmt.Errorf("manifest root must be an object")
	}
	commits := obj(m["source_commits"])
	if !validHex(str(commits, "orchestrator"), 40, 64) || !validHex(str(commits, "terrabase"), 40, 64) {
		return nil, nil, nil, fmt.Errorf("source_commits must contain full orchestrator and terrabase commit IDs")
	}
	names := InputNames
	profile, hasProfile := m["profile"]
	if !hasProfile {
		if str(m, "rust_test_name") != RustTestName {
			return nil, nil, nil, fmt.Errorf("rust_test_name must select the reviewed test %s", RustTestName)
		}
		if _, ok := m["go_test_name"]; ok {
			return nil, nil, nil, fmt.Errorf("legacy manifest cannot include managed-volume profile fields")
		}
		if _, ok := m["managed_volume"]; ok {
			return nil, nil, nil, fmt.Errorf("legacy manifest cannot include managed-volume profile fields")
		}
	} else if profile == ManagedVolumeProfile {
		names = ManagedVolumeInputNames
		if _, ok := m["rust_test_name"]; ok {
			return nil, nil, nil, fmt.Errorf("managed-volume manifest must not include rust_test_name")
		}
		if m["go_test_name"] != ManagedVolumeGoTestName {
			return nil, nil, nil, fmt.Errorf("go_test_name must select the reviewed test %s", ManagedVolumeGoTestName)
		}
		volume := obj(m["managed_volume"])
		if len(volume) != 1 || volume["filesystem_uuid"] != ManagedVolumeUUID {
			return nil, nil, nil, fmt.Errorf("managed_volume must pin filesystem_uuid %s", ManagedVolumeUUID)
		}
	} else {
		return nil, nil, nil, fmt.Errorf("unsupported qualification profile: %v", profile)
	}
	inputs := obj(m["inputs"])
	if len(inputs) != len(names) {
		return nil, nil, nil, fmt.Errorf("manifest inputs must contain exactly %v", names)
	}
	resolved := map[string]string{}
	identity := Object{}
	for _, name := range names {
		r := obj(inputs[name])
		expected := str(r, "sha256")
		supplied := str(r, "path")
		if !validHex(expected, 64, 64) {
			return nil, nil, nil, fmt.Errorf("input %s has an invalid sha256", name)
		}
		if !filepath.IsAbs(supplied) {
			return nil, nil, nil, fmt.Errorf("input %s path must be absolute", name)
		}
		actual, e := filepath.EvalSymlinks(supplied)
		if e != nil {
			return nil, nil, nil, e
		}
		info, e := os.Stat(actual)
		if e != nil {
			return nil, nil, nil, e
		}
		if !info.Mode().IsRegular() {
			return nil, nil, nil, fmt.Errorf("input %s is not a regular file", name)
		}
		digest, e := firecracker.Digest(actual)
		if e != nil {
			return nil, nil, nil, e
		}
		if digest != expected {
			return nil, nil, nil, fmt.Errorf("input %s SHA-256 mismatch", name)
		}
		if slices.Contains([]string{"firecracker", "go_host_test", "memberstatus_probe", "rust_server", "rust_test"}, name) && info.Mode().Perm()&0111 == 0 {
			return nil, nil, nil, fmt.Errorf("input %s is not executable", name)
		}
		resolved[name] = actual
		identity[name] = Object{"supplied_path": supplied, "resolved_path": actual, "sha256": digest, "size_bytes": info.Size()}
	}
	m = maps.Clone(m)
	m["inputs"] = identity
	m["profile"] = profile
	if !hasProfile {
		m["go_test_name"] = GoTestName
	}
	return m, raw, resolved, nil
}

result_parsers.text:
func lines(s string) []string {
	var result []string
	for line := range strings.SplitSeq(strings.TrimSuffix(s, "\n"), "\n") {
		result = append(result, strings.TrimSpace(line))
	}
	return result
}
func ParseGoTestOutput(output string, code int, name string) (Object, error) {
	var runs, passed []string
	skipped, failed, terminal := 0, 0, 0
	ls := lines(output)
	for _, line := range ls {
		if v, ok := strings.CutPrefix(line, "=== RUN   "); ok {
			runs = append(runs, v)
		}
		if v, ok := strings.CutPrefix(line, "--- PASS: "); ok {
			v, _, _ = strings.Cut(v, " (")
			passed = append(passed, v)
		}
		if strings.HasPrefix(line, "--- SKIP:") {
			skipped++
		}
		if strings.HasPrefix(line, "--- FAIL:") {
			failed++
		}
		if line == "PASS" {
			terminal++
		}
	}
	if code != 0 {
		return nil, fmt.Errorf("focused Go test exited %d", code)
	}
	if !slices.Equal(runs, []string{name}) {
		return nil, fmt.Errorf("focused Go test must run exactly %s; observed %v", name, runs)
	}
	if !slices.Equal(passed, []string{name}) || skipped != 0 || failed != 0 {
		return nil, fmt.Errorf("focused Go test result was not one explicit PASS")
	}
	if terminal != 1 || len(ls) == 0 || ls[len(ls)-1] != "PASS" {
		return nil, fmt.Errorf("focused Go test omitted its single terminal PASS result")
	}
	return Object{"name": name, "status": "PASS", "runs": 1, "skips": 0}, nil
}

var rustSummary = regexp.MustCompile(`^test result: (ok|FAILED)\. ([0-9]+) passed; ([0-9]+) failed; ([0-9]+) ignored; ([0-9]+) measured; ([0-9]+) filtered out; finished in .+$`)
var rustRunning = regexp.MustCompile(`^running ([0-9]+) tests?$`)
var rustLine = regexp.MustCompile(`^test (.+?) \.\.\.`)

func ParseRustTestOutput(output string, code int, name string) (Object, error) {
	var running, testLines []string
	var summaries [][]string
	for _, line := range lines(output) {
		if m := rustRunning.FindStringSubmatch(line); m != nil {
			running = append(running, m[1])
		}
		if m := rustLine.FindStringSubmatch(line); m != nil {
			testLines = append(testLines, m[1])
		}
		if m := rustSummary.FindStringSubmatch(line); m != nil {
			summaries = append(summaries, m)
		}
	}
	if code != 0 {
		return nil, fmt.Errorf("Rust member-status test exited %d", code)
	}
	if !slices.Equal(running, []string{"1"}) || !slices.Equal(testLines, []string{name}) {
		return nil, fmt.Errorf("Rust test must run exactly %s", name)
	}
	if len(summaries) != 1 {
		return nil, fmt.Errorf("Rust test must report one result summary")
	}
	s := summaries[0]
	if s[1] != "ok" || s[2] != "1" || s[3] != "0" || s[4] != "0" || s[5] != "0" {
		return nil, fmt.Errorf("Rust test did not report one non-ignored pass")
	}
	if strings.Count(output, MemberStatusSuccess) != 1 {
		return nil, fmt.Errorf("Rust test must include exactly one nested %s marker", MemberStatusSuccess)
	}
	if strings.Count(output, SenderSuccess) != 1 {
		return nil, fmt.Errorf("Rust test output must include the current sender-enabled Go probe success marker exactly once")
	}
	r := Object{"name": name, "status": "PASS", "runs": 1, "skips": 0, "nested_go_marker": MemberStatusSuccess, "sender_marker": SenderSuccess}
	for i, k := range []string{"passed", "failed", "ignored", "measured", "filtered"} {
		n, e := strconv.Atoi(s[i+2])
		if e != nil {
			return nil, e
		}
		r[k] = n
	}
	return r, nil
}

var serialService = regexp.MustCompile(`^\[\s*[0-9]+(?:\.[0-9]+)?\]\s+ts-member-status-qualification\[[0-9]+\]: (.*)$`)

func serialPayload(s string) []string {
	ls := lines(s)
	for i, line := range ls {
		if m := serialService.FindStringSubmatch(line); m != nil {
			ls[i] = m[1]
		}
	}
	return ls
}
func ParseRunnerResult(serial string, managed bool) (Object, error) {
	prefix, success := RunnerPrefix, RunnerSuccess
	stages := []string{"go-host-test", "rust-test", "runner"}
	if managed {
		prefix, success = VolumeRunnerPrefix, VolumeRunnerSuccess
		stages = []string{"go-host-test", "runner"}
	}
	var results []string
	for _, line := range serialPayload(serial) {
		if strings.HasPrefix(line, prefix) {
			results = append(results, line)
		}
	}
	if len(results) != 1 {
		return nil, fmt.Errorf("guest serial must contain exactly one terminal runner result; found %d", len(results))
	}
	r := results[0]
	if r == success {
		return Object{"status": "PASS"}, nil
	}
	m := regexp.MustCompile("^" + regexp.QuoteMeta(prefix) + `FAILED stage=([a-z0-9-]+) status=([1-9][0-9]{0,2})$`).FindStringSubmatch(r)
	if m == nil || !slices.Contains(stages, m[1]) {
		return nil, fmt.Errorf("guest serial contains a malformed runner result")
	}
	status, _ := strconv.Atoi(m[2])
	return Object{"status": "FAILED", "stage": m[1], "exit_status": status, "sentinel": r}, nil
}
func ParseQualificationResult(goOutput string, goCode int, rustOutput string, rustCode int, serial, name string) (Object, error) {
	g, e := ParseGoTestOutput(goOutput, goCode, GoTestName)
	if e != nil {
		return nil, e
	}
	r, e := ParseRustTestOutput(rustOutput, rustCode, name)
	if e != nil {
		return nil, e
	}
	runner, e := ParseRunnerResult(serial, false)
	if e != nil {
		return nil, e
	}
	if runner["status"] != "PASS" {
		return nil, fmt.Errorf("guest command failed stage=%v status=%v", runner["stage"], runner["exit_status"])
	}
	serial = strings.Join(serialPayload(serial), "\n")
	position := strings.Index(serial, RunnerSuccess)
	sender := strings.Index(serial, SenderSuccess)
	summary := strings.LastIndex(serial, "test result: ok.")
	if sender < 0 || position < sender {
		return nil, fmt.Errorf("guest runner PASS sentinel appeared before the Go sender probe succeeded")
	}
	if summary < 0 || position < summary {
		return nil, fmt.Errorf("guest runner PASS sentinel appeared before the Rust test result")
	}
	return Object{"go_host_test": g, "rust_test": r}, nil
}
func ParseManagedVolumeResult(goOutput string, code int, serial string) (Object, error) {
	g, e := ParseGoTestOutput(goOutput, code, ManagedVolumeGoTestName)
	if e != nil {
		return nil, e
	}
	runner, e := ParseRunnerResult(serial, true)
	if e != nil {
		return nil, e
	}
	if runner["status"] != "PASS" {
		return nil, fmt.Errorf("guest command failed stage=%v status=%v", runner["stage"], runner["exit_status"])
	}
	serial = strings.Join(serialPayload(serial), "\n")
	pattern := regexp.MustCompile(`managed-volume-v1 device=/dev/oracleoci/oraclevdb uuid=` + regexp.QuoteMeta(ManagedVolumeUUID) + ` mount=` + regexp.QuoteMeta(MountPath) + ` mount_id=([1-9][0-9]*) replication_shard=absent`)
	matches := pattern.FindAllStringSubmatchIndex(serial, -1)
	if len(matches) != 1 {
		return nil, fmt.Errorf("guest serial must contain exactly one managed-volume verification record")
	}
	m := matches[0]
	if m[0] >= strings.Index(serial, VolumeRunnerSuccess) {
		return nil, fmt.Errorf("guest runner PASS sentinel appeared before managed-volume verification")
	}
	id, e := strconv.ParseUint(serial[m[2]:m[3]], 10, 64)
	if e != nil {
		return nil, e
	}
	return Object{"go_host_test": g, "managed_volume": Object{"status": "PASS", "device": "/dev/oracleoci/oraclevdb", "filesystem_uuid": ManagedVolumeUUID, "mount_path": MountPath, "mount_id": id, "replication_shard": "absent"}}, nil
}

guest_file_read.text:
func GuestPath(root, path string) (string, error) {
	if !filepath.IsAbs(path) || slices.Contains(strings.Split(path, "/"), "..") {
		return "", fmt.Errorf("unsafe guest path: %s", path)
	}
	current := root
	parts := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for i, part := range parts {
		if part == "" {
			continue
		}
		current = filepath.Join(current, part)
		info, e := os.Lstat(current)
		if os.IsNotExist(e) {
			continue
		}
		if e != nil {
			return "", e
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return "", fmt.Errorf("guest path contains a symlink that could escape the image")
		}
		if i < len(parts)-1 && !info.IsDir() {
			return "", fmt.Errorf("guest path parent is not a directory")
		}
	}
	return filepath.Join(root, strings.TrimPrefix(path, "/")), nil
}
func ReadTextBounded(path string, maximum int64) (string, bool, error) {
	f, e := os.Open(path)
	if e != nil {
		return "", false, e
	}
	defer f.Close()
	b, e := io.ReadAll(io.LimitReader(f, maximum+1))
	if e != nil {
		return "", false, e
	}
	info, e := f.Stat()
	if e != nil {
		return "", false, e
	}
	return strings.ToValidUTF8(string(b[:min(int64(len(b)), maximum)]), "\uFFFD"), int64(len(b)) > maximum || info.Size() > maximum, nil
}
func ReadGuestRegularFile(root, path string, maximum int64) (string, bool, error) {
	host, e := GuestPath(root, path)
	if e != nil {
		return "", false, e
	}
	info, e := os.Lstat(host)
	if e != nil {
		return "", false, e
	}
	if !info.Mode().IsRegular() {
		return "", false, fmt.Errorf("guest evidence path is not a regular file")
	}
	return ReadTextBounded(host, maximum)
}

object_equality.text:
func canonical(v any) ([]byte, error) { return json.Marshal(v, json.Deterministic(true)) }
func equal(a, b any) bool {
	x, e := canonical(a)
	if e != nil {
		return false
	}
	y, e := canonical(b)
	return e == nil && bytes.Equal(x, y)
}

atomic_events.text:
func AtomicReplace(path string, value any) error {
	b, e := json.Marshal(value, json.Deterministic(true), jsontext.Multiline(true), jsontext.WithIndent("  "))
	if e != nil {
		return e
	}
	f, e := os.CreateTemp(filepath.Dir(path), ".evidence-")
	if e != nil {
		return e
	}
	defer os.Remove(f.Name())
	if _, e = f.Write(append(b, '\n')); e != nil {
		f.Close()
		return e
	}
	if e = f.Sync(); e != nil {
		f.Close()
		return e
	}
	if e = f.Close(); e != nil {
		return e
	}
	if e = os.Rename(f.Name(), path); e != nil {
		return e
	}
	d, e := os.Open(filepath.Dir(path))
	if e != nil {
		return e
	}
	defer d.Close()
	return d.Sync()
}

type EventLog struct {
	Path    string
	Entries []Object
	Err     error
}

func (e *EventLog) Add(event string, fields Object) {
	if fields == nil {
		fields = Object{}
	}
	fields["time"] = time.Now().UTC().Format(time.RFC3339Nano)
	fields["event"] = event
	e.Entries = append(e.Entries, fields)
	if e.Err == nil {
		e.Err = AtomicReplace(e.Path, e.Entries)
	}
}

bounded_output.text:
func NewBoundedOutput(path string, maximum int64) (*BoundedOutput, error) {
	f, e := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
	if e != nil {
		return nil, e
	}
	return &BoundedOutput{Path: path, Maximum: maximum, file: f}, nil
}
func (b *BoundedOutput) Write(p []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	length := len(p)
	room := max(int64(0), b.Maximum-b.Written)
	if int64(len(p)) > room {
		p = p[:room]
		b.Truncated = true
	}
	if b.file != nil && b.err == nil {
		n, e := b.file.Write(p)
		b.Written += int64(n)
		if e != nil {
			b.err = e
			b.Truncated = true
		}
	}
	return length, nil
}
func (b *BoundedOutput) Finish() (Object, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.file != nil {
		b.err = errors.Join(b.err, b.file.Sync(), b.file.Close())
		b.file = nil
	}
	return Object{"path": b.Path, "bytes_written": b.Written, "limit_bytes": b.Maximum, "truncated": b.Truncated}, b.err
}

command_runner.text:
func (r *CommandRunner) Pending() bool { return len(r.pending) > 0 }
func (r *CommandRunner) StopPending() []string {
	var errs []string
	pending := r.pending
	r.pending = nil
	for _, p := range pending {
		if e := p.Process.Stop(5*time.Second, false); e != nil {
			errs = append(errs, fmt.Sprintf("stop pending command process group %d (%s): %v", p.Process.PID(), p.Label, e))
			r.pending = append(r.pending, p)
			continue
		}
		result, e := p.Capture.Finish()
		if e != nil {
			errs = append(errs, e.Error())
		}
		r.Events.Add("pending_command_stopped", Object{"label": p.Label, "pid": p.Process.PID(), "returncode": p.Process.ExitCode, "output": result})
	}
	return errs
}
func (r *CommandRunner) Run(ctx context.Context, label string, args []string, timeout time.Duration, allowed []int) (int, string, error) {
	if r.Pending() {
		return 0, "", fmt.Errorf("refusing to start a command while an earlier process group is not confirmed stopped")
	}
	r.Sequence++
	log := filepath.Join(r.Root, "commands", fmt.Sprintf("%03d-%s.log", r.Sequence, label))
	maximum := r.Maximum
	if maximum == 0 {
		maximum = MaxCommandLogBytes
	}
	if e := AtomicReplace(log[:len(log)-4]+".json", Object{"label": label, "command": args, "timeout_seconds": timeout.Seconds(), "log": log, "log_limit_bytes": maximum}); e != nil {
		return 0, log, e
	}
	r.Events.Add("command_start", Object{"label": label, "command": args, "timeout_seconds": timeout.Seconds(), "log": log})
	if r.Events.Err != nil {
		return 0, log, r.Events.Err
	}
	capture, e := NewBoundedOutput(log, maximum)
	if e != nil {
		return 0, log, e
	}
	p, e := firecracker.Start(args, "", capture)
	if e != nil {
		capture.Finish()
		return 0, log, e
	}
	waitCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	finished := false
	for waitCtx.Err() == nil {
		exited, e := p.Exited()
		if e != nil {
			break
		}
		if exited {
			finished = true
			break
		}
		select {
		case <-waitCtx.Done():
		case <-time.After(20 * time.Millisecond):
		}
	}
	stopErr := p.Stop(time.Second, false)
	if stopErr != nil {
		if !p.Reaped {
			r.pending = append(r.pending, pendingCommand{label, p, capture})
		} else {
			_, captureErr := capture.Finish()
			stopErr = errors.Join(stopErr, captureErr)
		}
		return 0, log, fmt.Errorf("command cleanup failed: %w", stopErr)
	}
	result, logErr := capture.Finish()
	r.Events.Add("command_exit", Object{"label": label, "returncode": p.ExitCode, "log": log, "output": result})
	if !finished {
		return p.ExitCode, log, fmt.Errorf("command failed: timed out or interrupted after %s", timeout)
	}
	if logErr != nil {
		return p.ExitCode, log, fmt.Errorf("bounded log collection failed: %w", logErr)
	}
	if capture.Truncated {
		return p.ExitCode, log, fmt.Errorf("bounded command log was truncated")
	}
	if allowed == nil {
		allowed = []int{0}
	}
	if !slices.Contains(allowed, p.ExitCode) {
		return p.ExitCode, log, fmt.Errorf("command failed (%d): %v; log %s", p.ExitCode, args, log)
	}
	return p.ExitCode, log, nil
}

vm_api_requests.text:
func (v *VM) SocketPath() string { return filepath.Join(v.SocketDir, "api.sock") }
func unixRequest(ctx context.Context, socket, method, path string, payload Object) error {
	if method == "PUT" {
		return firecracker.UnixAPI(ctx, socket, path, payload)
	}
	transport := &http.Transport{DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
		return (&net.Dialer{}).DialContext(ctx, "unix", socket)
	}}
	defer transport.CloseIdleConnections()
	client := &http.Client{Transport: transport, Timeout: 5 * time.Second}
	r, e := http.NewRequestWithContext(ctx, method, "http://localhost"+path, nil)
	if e != nil {
		return e
	}
	response, e := client.Do(r)
	if e != nil {
		return e
	}
	defer response.Body.Close()
	_, e = io.Copy(io.Discard, io.LimitReader(response.Body, 1<<20))
	if e != nil {
		return e
	}
	if response.StatusCode != 200 && response.StatusCode != 204 {
		return fmt.Errorf("Firecracker %s %s: HTTP %d", method, path, response.StatusCode)
	}
	return nil
}
func (v *VM) api(ctx context.Context, method, path string, payload Object) error {
	if v.API != nil {
		return v.API(ctx, method, path, payload)
	}
	return unixRequest(ctx, v.SocketPath(), method, path, payload)
}
func (v *VM) Requests() []APIRequest {
	r := []APIRequest{{"PUT", "/machine-config", Object{"vcpu_count": GuestVCPUs, "mem_size_mib": GuestRAMMiB, "smt": false}}, {"PUT", "/boot-source", Object{"kernel_image_path": v.Kernel, "boot_args": BootArgs}}, {"PUT", "/drives/rootfs", Object{"drive_id": "rootfs", "path_on_host": v.Image, "is_root_device": true, "is_read_only": false}}}
	if v.ManagedVolume != "" {
		r = append(r, APIRequest{"PUT", "/drives/" + ManagedVolumeDriveID, Object{"drive_id": ManagedVolumeDriveID, "path_on_host": v.ManagedVolume, "is_root_device": false, "is_read_only": false}})
	}
	return append(r, APIRequest{"PUT", "/actions", Object{"action_type": "InstanceStart"}})
}

vm_start.text:
func (v *VM) Start(ctx context.Context) error {
	if len([]byte(v.SocketPath())) >= 100 {
		return fmt.Errorf("Firecracker API socket path must be shorter than 100 bytes")
	}
	var e error
	v.Serial, e = NewBoundedOutput(filepath.Join(v.Logs, "guest-serial.log"), MaxSerialLogBytes)
	if e != nil {
		return e
	}
	v.VMM, e = NewBoundedOutput(filepath.Join(v.Logs, "firecracker-vmm.log"), MaxCommandLogBytes)
	if e != nil {
		v.Serial.Finish()
		return e
	}
	start := v.StartProcess
	if start == nil {
		start = func(args []string, stdout, stderr io.Writer) (*firecracker.Process, error) {
			cmd := exec.Command(args[0], args[1:]...)
			cmd.Stdout = stdout
			cmd.Stderr = stderr
			cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
			cmd.WaitDelay = 2 * time.Second
			if e := cmd.Start(); e != nil {
				return nil, e
			}
			return &firecracker.Process{Cmd: cmd}, nil
		}
	}
	command := []string{v.Firecracker, "--api-sock", v.SocketPath(), "--log-path", "/dev/stderr"}
	v.Process, e = start(command, v.Serial, v.VMM)
	if e != nil {
		v.Serial.Finish()
		v.VMM.Finish()
		return e
	}
	v.Events.Add("firecracker_start", Object{"pid": v.Process.PID(), "command": command, "api_socket": v.SocketPath()})
	if v.Events.Err != nil {
		return v.Events.Err
	}
	deadline := time.Now().Add(20 * time.Second)
	ready := false
	for time.Now().Before(deadline) {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		exited, e := v.Process.Exited()
		if e != nil {
			return e
		}
		if exited {
			return fmt.Errorf("Firecracker exited before API became ready")
		}
		if _, e := os.Stat(v.SocketPath()); e == nil {
			if e = v.api(ctx, "GET", "/version", nil); e == nil {
				ready = true
				break
			}
		}
		time.Sleep(100 * time.Millisecond)
	}
	if !ready {
		return fmt.Errorf("Firecracker API socket did not become ready in 20s")
	}
	for _, r := range v.Requests() {
		if e = v.api(ctx, r.Method, r.Path, r.Payload); e != nil {
			return e
		}
	}
	v.Events.Add("guest_boot", Object{"pid": v.Process.PID(), "memory_mib": GuestRAMMiB, "vcpus": GuestVCPUs, "network_interfaces": []any{}})
	return nil
}

vm_output.text:
func (v *VM) FinishOutput() error {
	v.Output = Object{}
	var errs []error
	for _, entry := range []struct {
		name    string
		capture *BoundedOutput
	}{{"serial", v.Serial}, {"vmm", v.VMM}} {
		if entry.capture == nil {
			continue
		}
		r, e := entry.capture.Finish()
		if e != nil {
			errs = append(errs, e)
		}
		v.Output[entry.name] = r
		if entry.capture.Truncated {
			errs = append(errs, fmt.Errorf("Firecracker output log was truncated: %s", entry.name))
		}
	}
	v.Events.Add("firecracker_output_collected", Object{"output": v.Output})
	return errors.Join(errs...)
}

vm_stop.text:
func (v *VM) Stop(ctx context.Context) []string {
	var errs []string
	if v.Process == nil {
		return nil
	}
	if !v.ProcessGroupStopped {
		done, e := v.Process.Exited()
		if e != nil {
			errs = append(errs, e.Error())
		}
		if !done {
			if e = v.api(ctx, "PUT", "/actions", Object{"action_type": "SendCtrlAltDel"}); e != nil {
				errs = append(errs, fmt.Sprintf("send guest CtrlAltDel: %v", e))
			}
			v.Process.WaitUnreaped(25 * time.Second)
		}
		if e = v.Process.Stop(5*time.Second, false); e != nil {
			errs = append(errs, fmt.Sprintf("stop Firecracker process group: %v", e))
		} else {
			v.ProcessGroupStopped = true
		}
	}
	if !v.ProcessGroupStopped {
		errs = append(errs, "Firecracker process group is not confirmed stopped")
	} else if len(v.Output) == 0 {
		if e := v.FinishOutput(); e != nil {
			errs = append(errs, e.Error())
		}
	}
	if len(errs) == 0 {
		v.Events.Add("firecracker_stopped", Object{"pid": v.Process.PID(), "returncode": v.Process.ExitCode})
	}
	return errs
}

file_digest.text:
func Digest(path string) (string, error) {
	f, e := os.Open(path)
	if e != nil {
		return "", e
	}
	defer f.Close()
	h := sha256.New()
	if _, e = io.Copy(h, f); e != nil {
		return "", e
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

process_start.text:
func Start(argv []string, dir string, output io.Writer) (*Process, error) {
	if len(argv) == 0 {
		return nil, errors.New("empty command")
	}
	c := exec.Command(argv[0], argv[1:]...)
	c.Dir = dir
	c.Stdout = output
	c.Stderr = output
	c.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	c.WaitDelay = 2 * time.Second
	if e := c.Start(); e != nil {
		return nil, e
	}
	return &Process{Cmd: c}, nil
}

process_observation.text:
func (p *Process) PID() int { return p.Cmd.Process.Pid }
func (p *Process) Exited() (bool, error) {
	if p.Reaped {
		return true, nil
	}
	if p.hooks != nil && p.hooks.exited != nil {
		return p.hooks.exited()
	}
	var info unix.Siginfo
	e := unix.Waitid(unix.P_PID, p.PID(), &info, unix.WEXITED|unix.WNOHANG|unix.WNOWAIT, nil)
	if e != nil {
		return false, fmt.Errorf("owned process %d was reaped before cleanup: %w", p.PID(), e)
	}
	return info.Signo != 0, nil
}
func (p *Process) Group() (int, error) {
	if p.Reaped {
		return 0, fmt.Errorf("owned process %d was reaped before group cleanup", p.PID())
	}
	group := syscall.Getpgid
	if p.hooks != nil && p.hooks.group != nil {
		group = p.hooks.group
	}
	id, e := group(p.PID())
	if e != nil {
		return 0, e
	}
	if id != p.PID() {
		return 0, fmt.Errorf("owned process %d is no longer its process-group leader", p.PID())
	}
	return id, nil
}

process_group_members.text:
func LiveProcessGroupMembers(pgid int) ([]int, error) {
	entries, e := os.ReadDir("/proc")
	if e != nil {
		return nil, e
	}
	members := []int{}
	for _, entry := range entries {
		pid, e := strconv.Atoi(entry.Name())
		if e != nil {
			continue
		}
		b, e := os.ReadFile(filepath.Join("/proc", entry.Name(), "stat"))
		if processStatGone(e) {
			continue
		}
		if e != nil {
			return nil, e
		}
		_, after, ok := strings.CutLast(string(b), ")")
		if !ok {
			return nil, fmt.Errorf("invalid process status for %d", pid)
		}
		f := strings.Fields(after)
		if len(f) < 3 {
			return nil, fmt.Errorf("invalid process status for %d", pid)
		}
		id, e := strconv.Atoi(f[2])
		if e != nil {
			return nil, e
		}
		if id == pgid && !slices.Contains([]string{"Z", "X", "x"}, f[0]) {
			members = append(members, pid)
		}
	}
	return members, nil
}

// A process can disappear after its stat file opens, returning ESRCH instead of ENOENT.
func processStatGone(err error) bool {
	return errors.Is(err, os.ErrNotExist) || errors.Is(err, syscall.ESRCH)
}

process_quiescence.text:
func WaitProcessGroupQuiescent(pgid int, timeout time.Duration) error {
	deadline := time.Now().Add(timeout)
	for {
		members, e := LiveProcessGroupMembers(pgid)
		if e != nil {
			return e
		}
		if len(members) == 0 {
			return nil
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("owned process group %d still has live members: %v", pgid, members)
		}
		time.Sleep(50 * time.Millisecond)
	}
}

process_wait.text:
func (p *Process) WaitUnreaped(timeout time.Duration) (bool, error) {
	if p.hooks != nil && p.hooks.wait != nil {
		return p.hooks.wait(timeout)
	}
	deadline := time.Now().Add(timeout)
	for {
		done, e := p.Exited()
		if e != nil || done {
			return done, e
		}
		if time.Now().After(deadline) {
			return false, nil
		}
		time.Sleep(50 * time.Millisecond)
	}
}

process_stop.text:
func (p *Process) Stop(timeout time.Duration, kill bool) error {
	id, e := p.Group()
	if e != nil {
		return e
	}
	if !kill {
		if e = p.signalGroup(id, syscall.SIGTERM); e != nil && !errors.Is(e, syscall.ESRCH) {
			return e
		}
		if _, e = p.WaitUnreaped(timeout); e != nil {
			return e
		}
		if _, e = p.Group(); e != nil {
			return e
		}
	}
	if e = p.signalGroup(id, syscall.SIGKILL); e != nil && !errors.Is(e, syscall.ESRCH) {
		return e
	}
	quiescent := WaitProcessGroupQuiescent
	if p.hooks != nil && p.hooks.quiescent != nil {
		quiescent = p.hooks.quiescent
	}
	if e = quiescent(id, timeout); e != nil {
		return e
	}
	if p.hooks != nil && p.hooks.reap != nil {
		e = p.hooks.reap()
	} else {
		e = p.Cmd.Wait()
	}
	p.Reaped = true
	if p.Cmd.ProcessState != nil {
		p.ExitCode = p.Cmd.ProcessState.ExitCode()
	}
	if _, ok := errors.AsType[*exec.ExitError](e); ok {
		e = nil
	}
	if p.Output != nil {
		e = errors.Join(e, p.Output.Close())
		p.Output = nil
	}
	return e
}
func (p *Process) signalGroup(id int, signal syscall.Signal) error {
	if p.hooks != nil && p.hooks.signal != nil {
		return p.hooks.signal(id, signal)
	}
	return syscall.Kill(-id, signal)
}

