func Root(t testing.TB) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("cannot locate repository test support")
	}
	return filepath.Clean(filepath.Join(filepath.Dir(file), "../../.."))
}

func Write(t testing.TB, path string, data []byte, mode os.FileMode) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, data, mode); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, mode); err != nil {
		t.Fatal(err)
	}
}

func Read(t testing.TB, path string) []byte {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

script_exec.text:
func Exec(t *testing.T, dir string, env map[string]string, name string, args ...string) Result {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 3*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error { return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL) }
	cmd.WaitDelay = 2 * time.Second
	cmd.Dir = dir
	cmd.Env = os.Environ()
	for key, value := range env {
		prefix := key + "="
		for i := len(cmd.Env) - 1; i >= 0; i-- {
			if strings.HasPrefix(cmd.Env[i], prefix) {
				cmd.Env = append(cmd.Env[:i], cmd.Env[i+1:]...)
			}
		}
		cmd.Env = append(cmd.Env, prefix+value)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err := cmd.Run()
	if ctx.Err() != nil {
		t.Fatalf("%s exceeded its command deadline: %v", name, ctx.Err())
	}
	code := 0
	if err != nil {
		if exit, ok := errors.AsType[*exec.ExitError](err); ok {
			code = exit.ExitCode()
		} else {
			t.Fatalf("start %s: %v", name, err)
		}
	}
	return Result{stdout.String(), stderr.String(), code}
}

links_new.text:
func New(local string, conn *nats.Conn, configured []string, timeout time.Duration) (*Links, error) {
	token, err := protocol.RegionToken(local)
	if err != nil {
		return nil, err
	}
	if timeout <= 0 {
		timeout = DefaultTimeout
	}
	links := &Links{local: token, timeout: timeout, conns: map[string]*nats.Conn{}}
	links.regions = append(links.regions, token)
	for _, region := range configured {
		if regionToken, err := protocol.RegionToken(region); err == nil && regionToken != protocol.GlobalScope &&
			!slices.Contains(links.regions, regionToken) {
			links.regions = append(links.regions, regionToken)
		}
	}
	slices.Sort(links.regions[1:])
	if conn != nil {
		links.conns[token] = conn
	}
	return links, nil
}

links_mutation.text:
func (links *Links) Link(region string, conn *nats.Conn) error {
	token, err := protocol.RegionToken(region)
	if err != nil || token == protocol.GlobalScope {
		return protocol.ErrInvalidSubjectToken
	}
	links.mu.Lock()
	defer links.mu.Unlock()
	if !slices.Contains(links.regions, token) {
		links.regions = append(links.regions, token)
		slices.Sort(links.regions[1:])
	}
	if conn == nil {
		delete(links.conns, token)
	} else {
		links.conns[token] = conn
	}
	return nil
}

// Unlink drops a peer region: it leaves the configured set and its connection
// is released. The local region and unknown regions are left alone.
func (links *Links) Unlink(region string) {
	token, err := protocol.RegionToken(region)
	if err != nil || token == links.local {
		return
	}
	links.mu.Lock()
	defer links.mu.Unlock()
	if index := slices.Index(links.regions, token); index > 0 {
		links.regions = slices.Delete(links.regions, index, index+1)
		delete(links.conns, token)
	}
}

links_local_views.text:
func (links *Links) Local() string { return links.local }

// Regions returns every configured region, local first.
func (links *Links) Regions() []string {
	links.mu.RLock()
	defer links.mu.RUnlock()
	return slices.Clone(links.regions)
}

// Linked reports whether region has a connection.
func (links *Links) Linked(region string) bool {
	links.mu.RLock()
	defer links.mu.RUnlock()
	_, ok := links.conns[strings.ToLower(region)]
	return ok
}

links_request.text:
func (links *Links) Request(ctx context.Context, region, leaf string, payload []byte) ([]byte, error) {
	region = strings.ToLower(region)
	links.mu.RLock()
	conn, linked := links.conns[region]
	configured := slices.Contains(links.regions, region)
	links.mu.RUnlock()
	if !configured {
		return nil, ErrUnknownRegion
	}
	if !linked {
		return nil, ErrNotLinked
	}
	subject, err := protocol.ObservabilitySubject(region, leaf)
	if err != nil {
		return nil, err
	}
	// Always bound the request by the link timeout; an earlier caller
	// deadline still wins, a later one does not stretch it.
	ctx, cancel := context.WithTimeout(ctx, links.timeout)
	defer cancel()
	message, err := conn.RequestMsgWithContext(ctx, &nats.Msg{Subject: subject, Data: payload, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return nil, err
	}
	return message.Data, nil
}

region_tokens.text:
func CanonicalRegion(region string) (string, error) {
	if region == "" || len(region) > 63 {
		return "", fmt.Errorf("%w: region length is out of bounds", ErrInvalidSubjectToken)
	}
	region = strings.ToUpper(region)
	if region == "GLOBAL" {
		return region, nil
	}
	previousHyphen := true
	for _, character := range region {
		if character == '-' {
			if previousHyphen {
				return "", ErrInvalidSubjectToken
			}
			previousHyphen = true
			continue
		}
		if character < 'A' || character > 'Z' {
			if character < '0' || character > '9' {
				return "", ErrInvalidSubjectToken
			}
		}
		previousHyphen = false
	}
	if previousHyphen {
		return "", ErrInvalidSubjectToken
	}
	return region, nil
}

func RegionToken(region string) (string, error) {
	canonical, err := CanonicalRegion(region)
	if err != nil {
		return "", err
	}
	return strings.ToLower(canonical), nil
}

func RegionalRoot(region string) (string, error) {
	token, err := RegionToken(region)
	if err != nil || token == GlobalScope {
		return "", ErrInvalidSubjectToken
	}
	return SubjectRoot + "." + token, nil
}

observability_subject.text:
func ObservabilitySubject(region, leaf string) (string, error) {
	return regionalSubject(region, "obs", leaf)
}

regional_subject.text:
func regionalSubject(region, family, leaf string) (string, error) {
	if err := ValidateSubjectToken(leaf); err != nil {
		return "", err
	}
	root, err := RegionalRoot(region)
	if err != nil {
		return "", err
	}
	return root + "." + family + "." + leaf, nil
}

trace_header.text:
func TraceHeader(ctx context.Context, header nats.Header) nats.Header {
	traceparent := Traceparent(ctx)
	if traceparent == "" {
		return header
	}
	if header == nil {
		header = nats.Header{}
	}
	header.Set(traceparentHeader, traceparent)
	return header
}

